script:
frappe.ui.form.on('Sick Off Application', {
    patient: function(frm) {
        if (frm.doc.patient) {
            frappe.db.get_doc('Timaflor Patient', frm.doc.patient)
            .then(doc => {
                frm.set_value('employee_number', doc.employee_number);
                frm.set_value('department', doc.department);
            });
        }
    },
    total_sick_off_days_due: function(frm) {
        calculate_balance(frm);
    },
    sick_off_days_taken_to_date: function(frm) {
        calculate_balance(frm);
    },
    sick_off_days_approved: function(frm) {
        calculate_balance(frm);
    }
});

function calculate_balance(frm) {
    let total = frm.doc.total_sick_off_days_due || 0;
    let taken = frm.doc.sick_off_days_taken_to_date || 0;
    let approved = frm.doc.sick_off_days_approved || 0;

    frm.set_value('sick_off_days_balance', total - taken - approved);
}

frappe.ui.form.on('Accident Injury Report', {
    patient: function(frm) {
        if (frm.doc.patient) {
            frappe.db.get_doc('Timaflor Patient', frm.doc.patient)
            .then(doc => {
                frm.set_value('employee_number', doc.employee_number);
                frm.set_value('department', doc.department);
                frm.set_value('age', doc.age);
                frm.set_value('gender', doc.gender);
            });
        }
    }
});

frappe.ui.form.on('External Referral', {
    patient: function(frm) {
        if (frm.doc.patient) {
            frappe.db.get_doc('Timaflor Patient', frm.doc.patient)
            .then(doc => {
                frm.set_value('employee_number', doc.employee_number);
                frm.set_value('department', doc.department);
            });
        }
    }
});

frappe.ui.form.on('First Aid Entry', {
    entries_add: function(frm) {
        calculate_total(frm);
    },
    entries_remove: function(frm) {
        calculate_total(frm);
    }
});

function calculate_total(frm) {
    frm.set_value('total_cases', frm.doc.entries ? frm.doc.entries.length : 0);
}

frappe.ui.form.on('Timaflor Patient Encounter', {
    refresh: function(frm) {
        frm.set_query('patient', function() {
            return {
                query: 'healthcare.farm_clinic_hooks.search_timaflor_patient'
            };
        });
    },

    patient: function(frm) {
        if (!frm.doc.patient) {
            frm.set_intro('');
            frm.set_value('employee_number', '');
            frm.set_value('department', '');
            return;
        }
        setTimeout(function() {
            frappe.db.get_doc('Timaflor Patient', frm.doc.patient)
            .then(doc => {
                frm.set_value('employee_number', doc.employee_number);
                frm.set_value('department', doc.department);
                frm.set_intro(
                    `<b>👤 ${doc.full_name}</b> &nbsp;|&nbsp; 
                     🪪 ${doc.employee_number || 'No Employee No'} &nbsp;|&nbsp; 
                     🏭 ${doc.department || 'No Department'} &nbsp;|&nbsp;
                     ⚧ ${doc.gender || '-'} &nbsp;|&nbsp;
                     🎂 Age: ${doc.age || '-'}`,
                    'blue'
                );
            });
        }, 500);
    },

    referral_required: function(frm) {
        if (frm.doc.referral_required) {
            frappe.msgprint({
                title: 'Referral Required',
                message: 'Please remember to create an External Referral document for this patient.',
                indicator: 'orange'
            });
        }
    },

    sick_off_required: function(frm) {
        if (frm.doc.sick_off_required) {
            frappe.msgprint({
                title: 'Sick Off Required',
                message: 'Please remember to create a Sick Off Application for this patient.',
                indicator: 'blue'
            });
        }
    }
});
